    self._size = 0

  def empty(self):
    return not self.head

  def size(self):
    return self._size

  def push(self, val):
    new = Node(val)
    if self.tail:
      self.tail.next = new
    self.tail = new
    if not self.head:
      self.head = new
    self._size += 1

  def pop(self):
    if self.empty():
      return None
    val = self.head.val
    self.head = self.head.next
    if not self.head:
      self.tail = None
    self._size -= 1
    return val

