class Node {
  int val;
  Node next;

  Node(int x) {
    val = x;
    next = null;
  }
}

class LinkedListQueue {
  private Node head;
  private Node tail;
  private int size;

  public LinkedListQueue() {
    head = null;
    tail = null;
    size = 0;
  }

  public boolean empty() {
    return head == null;
  }

  public int size() {
    return size;
  }

  public void push(int val) {
    Node newNode = new Node(val);
    if (tail != null) {
      tail.next = newNode;
    }
    tail = newNode;
    if (head == null) {
      head = newNode;
    }
    size++;
  }

  public Integer pop() {
    if (empty()) {
      return null;
    }
    Integer val = head.val;
    head = head.next;
    if (head == null) {
      tail = null;
    }
    size--;
    return val;
  }
}

