    queue.push(10);
    if (queue.size() != 1) {
      throw new RuntimeException(String.format(
          "\nsize(): got: %d, want: 1\n", queue.size()));
    }

    // Test push and pop
    queue.push(20);
    if (queue.pop() != 10) {
      throw new RuntimeException("\npop() should return 10\n");
    }
    if (queue.size() != 1) {
      throw new RuntimeException(String.format(
          "\nsize(): got: %d, want: 1\n", queue.size()));
    }

    // Test empty
    if (queue.empty()) {
      throw new RuntimeException("\nempty() should return false\n");
    }
    queue.pop();
    if (!queue.empty()) {
